    -- auto-link to existing families by child ת"ז (mirrors the API auto-match)
    UPDATE childsmile_app_voucherrecipient r
    SET linked_child_id = c.child_id
    FROM childsmile_app_children c
    WHERE r.distribution_id = d_pesach
      AND r.linked_child_id IS NULL
      AND r.child_id_number ~ '^[0-9]+$'
      AND c.child_id = r.child_id_number::bigint;
